    -- addon:data.mountdesc.60140:text
    ["A common sight on trade routes all across Azeroth, this calm, stalwart mount is the favorite of merchants traveling to exotic and distant markets."] = "Spectacle courant sur les routes commerciales d'Azeroth, cette monture calme et robuste est la préférée des marchands qui se rendent sur des marchés lointains et exotiques.",
    -- addon:data.petdesc.10709:text
    ["A complex system of burrows protects the prairie dog from its neighbors' massive hooves."] = "Un réseau complexe de terriers protège le chien de prairie des sabots massifs de ses voisins.",
    -- addon:data.petdesc.10713:text
    ["A favored companion of Kirin Tor magi, this reptile makes one wonder whether it's truly a snake or something else altogether."] = "Compagnon favori des mages du Kirin Tor, ce reptile laisse planer le doute : est-ce vraiment un serpent, ou tout autre chose ?",
    -- addon:data.mountdesc.458:text
