    -- addon:data.mountdesc.68056:text
    ["A few of the Argent Crusade's swiftest mounts were awarded to those members of the Horde who performed exceptionally during the tournament in Icecrown."] = "Quelques-unes des montures les plus rapides de la Croisade d'argent ont été offertes aux membres de la Horde qui se sont illustrés lors du tournoi de la Couronne de glace.",
    -- addon:data.petdesc.65682:text
    ["A fighting robot fueled by delicious red or blue electrolytes."] = "Un robot de combat alimenté par de délicieux électrolytes rouges ou bleus.",
    -- addon:toolbelt.chat_forge:text
    ["A forge and an anvil stand beside you for {minutes} minutes."] = "Une forge et une enclume se dressent à vos côtés pendant {minutes} minutes.",
    -- addon:data.petdesc.69535:text
    ["A gift from the Wildhammer dwarves to the heroes of the Alliance, these hatchlings are descendants of the same gryphons ridden by Falstad and his entourage into Grim Batol."] = "Cadeau des nains Marteau-hardi aux héros de l'Alliance, ces nouveau-nés descendent des mêmes griffons que montaient Falstad et sa suite jusqu'à Grim Batol.",
    -- addon:editMode.a_layout_named_name_already_exists:text
