    -- addon:data.mountdesc.22721:text
    ["Bred from the same vicious line of raptors which sired Ohgan and brought victory to the Gurubashi Empire."] = "Issu de la même lignée féroce de raptors qui engendra Ohgan et apporta la victoire à l'empire Gurubashi.",
