    -- addon:perks.spec_banner_sub:text
    ["Each card is one specialization (icon above its name). Every 10 levels of this run, you will get three echoes of the one you take"] = "Chaque carte est une spécialisation (icône au-dessus de son nom). Tous les 10 niveaux de cette expédition, vous recevrez trois Echos de celle que vous choisirez",
