    -- addon:data.affix_text.every_12_sec_shields_you_for_value_3_val:text
    ["Every 12 sec, shields you for @value@3%@value@ @range@[1,2%-6%]@range@ of your maximum health for 12 sec (Does not stack)"] = "Every 12 sec, shields you for @value@3%@value@ @range@[1,2%-6%]@range@ of your maximum health for 12 sec (Does not stack)",
    -- addon:data.affix_text.every_12_sec_shields_you_for_value_4_val:text
