    -- addon:collections.cat_one_handed_maces:text
    ["One-Handed Maces"] = "Masses à une main",
    -- addon:collections.cat_one_handed_swords:text
    ["One-Handed Swords"] = "Epées à une main",
    -- addon:collections.gs_favorites_filter:text
    ["Only Favorites"] = "Favoris uniquement",
    -- addon:data.petdesc.48408:text
    ["Only heroes who have proven their valor through great acts are gifted one of these mystical serpentine creatures."] = "Seuls les héros ayant prouvé leur vaillance par de grands exploits reçoivent l'une de ces créatures serpentines mystiques.",
    -- addon:extBank.only_items_you_could_mail:text
    ["Only items you could mail to an alt can be stored: no soulbound, conjured or temporary items."] = "Seuls les objets que vous pourriez envoyer par courrier à un autre personnage peuvent être stockés : pas d'objets liés, invoqués ou temporaires.",
    -- addon:data.petdesc.33050:text
    ["Only magical wishes make magical crawdads. If you wish for a fish, fish for a wish."] = "Seuls les vœux magiques font les écrevisses magiques. Pour un poisson, faites un vœu ; pour un vœu, allez pêcher.",
    -- addon:trials.only_the_current_season_so:text
    ["Only the current season so far."] = "Seulement la saison en cours pour l'instant.",
    -- addon:data.mountdesc.44151:text
    ["Only the most talented engineers have the courage and the mental stamina to create a flying machine that boasts stability and safety.  Turbo-charging one is just crazy!"] = "Seuls les ingénieurs les plus doués ont le courage et l'endurance mentale nécessaires pour créer une machine volante à la fois stable et sûre. Lui mettre un turbo, c'est de la folie !",
    -- addon:data.petdesc.66030:text
    ["Only the rarest of murlocs is able to successfully cross dimensional barriers. Fewer still return with the kind of advanced armor and weaponry possessed by Grunty."] = "Seul le plus rare des murlocs parvient à franchir les barrières dimensionnelles. Plus rares encore sont ceux qui reviennent avec l'armure et l'armement de pointe que possède Grognie.",
    -- addon:data.mountdesc.43688:text
    ["Only the swiftest heroes venturing into the troll temple of Zul'Aman were able to subdue these rare battle mounts."] = "Seuls les héros les plus rapides qui s'aventurèrent dans le temple troll de Zul'Aman parvinrent à dompter ces rares montures de combat.",
    -- addon:knowledgeBase.only_works_if_you_are:text
    ["Only works if you are stuck below the map or as a ghost."] = "Ne fonctionne que si vous êtes coincé sous la carte ou sous forme de fantôme.",
