    -- addon:data.graveyard.the_hinterlands_aerie_peak:text
    ["The Hinterlands, Aerie Peak"] = "Les Hinterlands, Nid-de-l'Aigle,",
    -- addon:data.graveyard.the_hinterlands_seradane:text
    ["The Hinterlands, Seradane"] = "Les Hinterlands, Seradane",
    -- addon:data.graveyard.the_hinterlands_shadra_alor:text
    ["The Hinterlands, Shadra'Alor"] = "Les Hinterlands, Shadra'Alor",
    -- addon:data.graveyard.the_hinterlands_the_overlook_cliffs:text
    ["The Hinterlands, The Overlook Cliffs"] = "Les Hinterlands, les Hauts-Surplombs",
    -- addon:data.mountdesc.32242:text
    ["The Horde had dragons, we had the gryphons. We won that war. - Ilsa Blusterbrew"] = "La Horde avait des dragons, nous avions les griffons. Nous avons gagné cette guerre. - Ilsa Fulminebière",
    -- addon:data.prestige.the_horseman_s_burning_greatblade:text
    ["The Horseman's Burning Greatblade"] = "Grande lame ardente du Cavalier",
    -- addon:data.boss.the_illidari_council:text
    ["The Illidari Council"] = "Le conseil illidari",
    -- addon:data.boss.the_iron_council:text
    ["The Iron Council"] = "Le conseil de fer",
    -- addon:data.boss.the_lich_king:text
    ["The Lich King"] = "Le roi-liche",
    -- addon:data.boss.the_lost_dwarves:text
    ["The Lost Dwarves"] = "Les nains perdus",
    -- addon:data.boss.the_lurker_below:text
    ["The Lurker Below"] = "Le Rôdeur d'En bas",
    -- addon:data.boss.the_maker:text
    ["The Maker"] = "Le Faiseur",
    -- addon:callboard.the_milestones_of_the_tree:text
    ["The Milestones of the tree: the percentage bonuses on the stats of your gear."] = "Les Jalons de l'arbre : les bonus en pourcentage aux caractéristiques de votre équipement.",
    -- addon:data.waystone.the_nexus:text
    ["The Nexus"] = "Le Nexus",
    -- addon:data.instance.the_obsidian_sanctum:text
    ["The Obsidian Sanctum"] = "Le sanctum Obsidien",
    -- addon:shop.featured_title:text
    ["The Panda Pet"] = "La mascotte panda",
    -- addon:skillTree.the_prestige_sector_of_the:text
    ["The Prestige sector of the tree: talents, echoes, resurrections, experience."] = "Le secteur Prestige de l'arbre : talents, Echos, résurrections, expérience.",
    -- addon:callboard.the_professions_sector_of_the:text
    ["The Professions sector of the tree: gathering, crafting and the Torment recipes."] = "Le secteur Métiers de l'arbre : récolte, artisanat et recettes du Tourment.",
    -- addon:data.boss.the_prophet_skeram:text
    ["The Prophet Skeram"] = "Le prophète Skeram",
    -- addon:data.boss.the_prophet_tharon_ja:text
    ["The Prophet Tharon'ja"] = "Le prophète Tharon'ja",
    -- addon:raidFinder.the_raid_finder_opens_at_level_80:text
    ["The Raid Finder opens at level 80."] = "La Recherche de raid s'ouvre au niveau 80.",
    -- addon:data.boss.the_ravenian:text
    ["The Ravenian"] = "Le Voracien",
    -- addon:reaper.the_reaper_does_not_answer:text
    ["The Reaper does not answer on this realm."] = "Le Faucheur ne répond pas sur ce royaume.",
    -- addon:playerRun.the_reaper_s_gaze:text
    ["The Reaper's Gaze"] = "Le regard du Faucheur",
    -- addon:data.instance.the_ruby_sanctum:text
    ["The Ruby Sanctum"] = "Le sanctum Rubis",
    -- addon:data.waystone.the_sepulcher_silverpine_forest:text
    ["The Sepulcher, Silverpine Forest"] = "Le Sépulcre, forêt des Pins argentés",
    -- addon:data.boss.the_seven:text
    ["The Seven"] = "Les Sept",
    -- addon:data.waystone.the_shadow_vault_icecrown:text
    ["The Shadow Vault, Icecrown"] = "Le caveau des Ombres, Couronne de glace",
    -- addon:data.mountdesc.59797:text
    ["The Sons of Hodir believe that riding an ice-white mammoth will protect the rider from frostbite and snow blindness."] = "Les Fils de Hodir pensent que chevaucher un mammouth d'un blanc de glace protège le cavalier des engelures et de la cécité des neiges.",
    -- addon:data.waystone.the_stair_of_destiny_hellfire_peninsula:text
    ["The Stair of Destiny, Hellfire Peninsula"] = "L'escalier du Destin, Péninsule des Flammes infernales",
    -- addon:data.waystone.the_stockade:text
    ["The Stockade"] = "La Prison",
    -- addon:data.mountdesc.59996:text
    ["The Storm Peaks! There we will find the beast strong enough to bear me into battle. -Skadi the Ruthless"] = "Les pics Foudroyés ! C'est là que nous trouverons la bête assez forte pour me porter au combat. -Skadi le Brutal",
    -- addon:data.mountdesc.23510:text
    ["The Stormpike clan's mount trainers have a tradition of etching their names onto the left horn of every battle ram they raise."] = "Les dresseurs de montures du clan Foudrepique ont pour tradition de graver leur nom sur la corne gauche de chaque bélier de guerre qu'ils élèvent.",
    -- addon:data.waystone.the_stormspire_netherstorm:text
    ["The Stormspire, Netherstorm"] = "La Foudreflèche, Raz-de-Néant",
    -- addon:data.mountdesc.66088:text
    ["The Sunreavers of Dalaran select only the swiftest and most formidable of dragonhawks as their mounts."] = "Les Saccage-soleil de Dalaran ne choisissent pour montures que les faucons-dragons les plus rapides et les plus redoutables.",
    -- addon:data.instance.the_sunwell:text
    ["The Sunwell"] = "Le Puits de soleil",
    -- addon:data.waystone.the_temple_of_atal_hakkar:text
    ["The Temple of Atal'Hakkar"] = "Le temple d'Atal'Hakkar",
    -- addon:toolbelt.chat_loading:text
    ["The Toolbelt is still loading. Try again in a moment."] = "La Trousse à outils est encore en cours de chargement. Réessayez dans un instant.",
    -- addon:data.boss.the_unforgiven:text
    ["The Unforgiven"] = "Le Condamné",
    -- addon:voidStorage.the_void_storage:text
    ["The Void Storage"] = "La Chambre du Vide",
    -- addon:extBank.the_warband_bank_is_locked:text
    ["The Warband Bank is locked.\n\nUnlock it once and every character of your account\nshares its bags and its gold."] = "La banque de bataillon est verrouillée.\n\nDébloquez-la une fois et tous les personnages de votre compte\npartageront ses sacs et son or.",
    -- addon:shop.token_title:text
    ["The WoW Token"] = "Le jeton WoW",
    -- addon:data.mountdesc.44153:text
    ["The backbone of the Alliance air force is comprised predominantly of gnomish flying machines due to their maneuverability and speed."] = "L'ossature de l'armée de l'air de l'Alliance est composée en majorité d'engins volants gnomes, en raison de leur maniabilité et de leur vitesse.",
    -- addon:data.petdesc.62508:text
    ["The bears of Dun Morogh are prized for their hardiness, loyalty, and combat prowess. Their time among the dwarves does little to curb their ferocity."] = "Les ours de Dun Morogh sont prisés pour leur robustesse, leur loyauté et leurs prouesses au combat. Leur vie aux côtés des nains n'adoucit guère leur férocité.",
    -- addon:data.petdesc.65381:text
    ["The bouncy gurloc is a distant cousin of the murloc."] = "Le gurloc bondissant est un lointain cousin du murloc.",
    -- addon:data.petdesc.10716:text
    ["The brown snake is native to Horde-controlled territories. It seems unremarkable until its victims are within range."] = "Le serpent brun est originaire des territoires contrôlés par la Horde. Il semble banal jusqu'à ce que ses victimes soient à portée.",
    -- addon:prestige.the_button_opens_when_both:text
    ["The button opens when both are met: enough Soul Ashes committed to your Skill Tree, and at least 750 banked Soul Shards, so the reset always pays at least one Soul Essence.\n\nHover the locked button to see which one is still missing."] = "Le bouton s'ouvre quand les deux conditions sont remplies : assez de Cendres d'âme engagées dans votre Arbre des Cendres, et au moins 750 Eclats d'Âme en banque, pour que la réinitialisation rapporte toujours au moins une Essence d'âme.\n\nSurvolez le bouton verrouillé pour voir laquelle manque encore.",
    -- addon:prestige.the_button_opens_when_both_are_met_enoug:text
    ["The button opens when both are met: enough Soul Ashes committed to your Skill Tree, and enough banked Soul Shards for one Soul Essence, so the reset always pays at least one Soul Essence.\n\nHover the locked button to see which one is still missing."] = "Le bouton s'active quand les deux conditions sont remplies : assez de Cendres d'âme investies dans votre Arbre des Cendres, et assez d'Eclats d'Âme en banque pour une Essence d'âme, afin que la réinitialisation rapporte toujours au moins une Essence d'âme.\n\nSurvolez le bouton verrouillé pour voir laquelle manque encore.",
    -- addon:skillTree.the_cast_was_interrupted_your_changes_we:text
    ["The cast was interrupted, your changes were not applied."] = "L'incantation a été interrompue, vos modifications n'ont pas été appliquées.",
    -- addon:data.petdesc.61351:text
    ["The cobras of Azeroth are renowned for their fast-acting venom and swift strikes."] = "Les cobras d'Azeroth sont réputés pour leur venin à l'action rapide et leurs attaques fulgurantes.",
    -- addon:data.petdesc.10688:text
    ["The cockroach is usually an impulse buy. Its owners have a hard time parting with it even after numerous attempts."] = "Le cafard est généralement un achat impulsif. Ses maîtres ont du mal à s'en séparer, même après de nombreuses tentatives.",
    -- addon:journal.the_complete_catalog_echoes_you:text
    ["The complete catalog. Echoes you currently hold are not repeated here: they already sit on the left.\n\nEchoes with a |cffffd700book badge|r are sealed inside Tomes: greyed until you loot and learn their tome, then permanently yours."] = "Le catalogue complet. Les Echos que vous détenez actuellement n'y sont pas répétés : ils sont déjà à gauche.\n\nLes Echos marqués d'un |cffffd700badge de livre|r sont scellés dans des Tomes : grisés jusqu'à ce que vous ramassiez et appreniez leur Tome, puis acquis définitivement.",
    -- addon:core.the_count_starts_again_at_the_weekly_res:text
    ["The count starts again at the weekly reset."] = "Le compte repart de zéro à la réinitialisation hebdomadaire.",
    -- addon:data.petdesc.10717:text
    ["The crimson snake is favored among the Darkspear trolls for not only its vicious nature, but also its steadfast loyalty."] = "Le serpent cramoisi est apprécié des trolls Sombrelance non seulement pour sa nature féroce, mais aussi pour sa loyauté indéfectible.",
    -- addon:data.petdesc.43697:text
    ["The crocolisk's hide and meat are prized by hunters, but the beast is ferocious and seldom taken by surprise."] = "La peau et la viande du crocilisque sont prisées des chasseurs, mais la bête est féroce et rarement prise au dépourvu.",
    -- addon:callboard.the_currency_of_the_soul:text
    ["The currency of the Soul Ash Tree: every ordinary node, the flat stats, the mechanics and the infinite wells."] = "La monnaie de l'Arbre des Cendres d'âme : tous les nœuds ordinaires, les caractéristiques fixes, les mécaniques et les puits infinis.",
    -- addon:data.petdesc.67414:text
    ["The demand for this purple-skinned breed has drastically reduced the raptor population near the Wailing Caverns."] = "La demande pour cette race à la peau violette a fortement réduit la population de raptors près des Cavernes des Lamentations.",
    -- addon:playerRun.the_dungeon_runs_at_the:text
    ["The dungeon runs at the difficulty picked in the Dungeon Finder; your own difficulty returns when you leave."] = "Le donjon se joue à la difficulté choisie dans la Recherche de donjon ; votre propre difficulté revient quand vous en sortez.",
    -- addon:data.mountdesc.22720:text
    ["The dwarves value their ram companions for their fearlessness charging into battle."] = "Les nains apprécient leurs béliers pour l'intrépidité avec laquelle ils chargent au combat.",
    -- addon:collections.gs_transmogrify_illusion_invalid_item:text
    ["The equipped item cannot be transmogrified with enchants."] = "L'objet équipé ne peut pas être transmogrifié avec des enchantements.",
    -- addon:data.petdesc.35156:text
    ["The ethereal Rashaad began breeding these enigmatic creatures after learning of their ability to feed on arcane energies."] = "L'éthérien Rashaad s'est mis à élever ces créatures énigmatiques après avoir découvert qu'elles pouvaient se nourrir d'énergies arcaniques.",
    -- addon:data.mountdesc.72286:text
    ["The famous steed of Arthas Menethil, who serves its master in life and in death.  Riding him is truly a feat of strength."] = "Le célèbre destrier d'Arthas Menethil, qui sert son maître dans la vie comme dans la mort.  Le monter relève véritablement du tour de force.",
    -- addon:data.affix_text.the_fifth_frostbolt_on_the_same_target_f:text
    ["The fifth Frostbolt on the same target finishes the cooldown of Frost Nova and reduces the cooldown of Deep Freeze by @value@6@value@ @range@[2-6]@range@ sec (Does not stack)"] = "The fifth Frostbolt on the same target finishes the cooldown of Frost Nova and reduces the cooldown of Deep Freeze by @value@6@value@ @range@[2-6]@range@ sec (Does not stack)",
    -- addon:trials.the_first_wave_approaches:text
    ["The first wave approaches"] = "La première vague approche",
    -- addon:data.mountdesc.54753:text
    ["The frost vrykul believe that wearing a necklace of polar bear claws will grant them otherworldly strength."] = "Les vrykuls du givre croient que porter un collier de griffes d'ours polaire leur confère une force surnaturelle.",
    -- addon:raidFinder.the_group:text
    ["The group"] = "Le groupe",
    -- addon:callboard.the_higher_the_item_level:text
    ["The higher the item level you have ever worn, the more contracts a cache asks for."] = "Plus le niveau d'objet maximal que vous avez porté est élevé, plus une cache demande de contrats.",
    -- addon:torment.the_hold:text
    ["The hold"] = "La défense",
    -- addon:data.petdesc.10682:text
    ["The jungle trolls train these birds to mimic calls for help in order to lure unsuspecting travelers into traps."] = "Les trolls de la jungle dressent ces oiseaux à imiter des appels au secours pour attirer les voyageurs imprudents dans leurs pièges.",
    -- addon:core.the_killing_blow_was_not:text
    ["The killing blow was not recorded."] = "Le coup de grâce n'a pas été enregistré.",
    -- addon:data.mountdesc.16056:text
    ["The lack of spots or stripes marks this beast as a descendant of the most ancient frostsaber line."] = "L'absence de taches ou de rayures désigne cette bête comme une descendante de la plus ancienne lignée de sabres-de-givre.",
    -- addon:data.mountdesc.24252:text
    ["The last known Zulian tigers were kept by High Priest Thekal, deep within Zul'Gurub.  They are said to have been hunted into extinction."] = "Les derniers tigres zuliens connus étaient gardés par le Grand prêtre Thekal, au cœur de Zul'Gurub. On dit qu'ils ont été chassés jusqu'à l'extinction.",
    -- addon:data.petdesc.10676:text
    ["The last person who tried to housebreak this cat quickly learned that a soiled rug is better than a shredded everything-else."] = "Le dernier qui a voulu apprendre la propreté à ce chat a vite compris qu'un tapis souillé vaut mieux que tout le reste en lambeaux.",
    -- addon:data.affix_text.the_last_tick_of_explosive_shot_scatters:text
    ["The last tick of Explosive Shot scatters 3 explosive orbs around the target. Each explodes after 2 sec for @value@150%@value@ @range@[30%-150%]@range@ of your Attack Power as Fire damage to enemies within 4 yd (Does not stack)"] = "The last tick of Explosive Shot scatters 3 explosive orbs around the target. Each explodes after 2 sec for @value@150%@value@ @range@[30%-150%]@range@ of your Attack Power as Fire damage to enemies within 4 yd (Does not stack)",
    -- addon:data.petdesc.23811:text
    ["The legendary ale frog was believed to be extinct until the strange brews at the Darkmoon Faire brought them out of hiding."] = "On croyait la légendaire grenouille de bière éteinte, jusqu'à ce que les étranges breuvages de la Foire de Sombrelune la fassent sortir de sa cachette.",
    -- addon:data.petdesc.62562:text
    ["The long-term effects of the contamination caused by the Exodar are still under observation."] = "Les effets à long terme de la contamination causée par l'Exodar sont toujours à l'étude.",
    -- addon:toolbelt.tip_remote:text
    ["The loot of everything that dies near you is picked up for you, filtered by the rules below."] = "Le butin de tout ce qui meurt près de vous est ramassé à votre place, selon les règles ci-dessous.",
    -- addon:toolbelt.menu_eye_tip:text
    ["The loot of everything that dies near you is picked up for you. Filter what you keep."] = "Le butin de tout ce qui meurt près de vous est ramassé à votre place. Filtrez ce que vous gardez.",
    -- addon:toolbelt.panel_eye_sub:text
    ["The loot of everything that dies near you, picked up for you."] = "Le butin de tout ce qui meurt près de vous, ramassé à votre place.",
    -- addon:data.petdesc.39181:text
    ["The magical energies released during Skywing's transformation back into his true arakkoa form liberated this poor creature, a fledgling bird imprisoned by Luanga in order to power his fowl curse."] = "Les énergies magiques libérées quand Aile-du-ciel a retrouvé sa véritable forme d'arakkoa ont délivré cette pauvre créature, un oisillon emprisonné par Luanga pour alimenter sa malédiction aviaire.",
    -- addon:data.mountdesc.65642:text
    ["The mirror's not so you can look back, but so your foes can see something besides your tailpipes. -Rillie Spindlenut"] = "Le rétroviseur n'est pas là pour regarder en arrière, mais pour que vos ennemis voient autre chose que vos pots d'échappement. -Rillie Fuseboulon",
    -- addon:data.mountdesc.28828:text
    ["The moods of these tempestuous mounts are known to shift as unpredictably and as violently as their physical forms."] = "L'humeur de ces montures tempétueuses est réputée changer de façon aussi imprévisible et violente que leur forme physique.",
    -- addon:data.mountdesc.37015:text
    ["The most aggressive nether drakes were awarded those heroes who showed significant prowess and commitment in the gladiatorial arena."] = "Les drakes du Néant les plus agressifs étaient décernés aux héros ayant fait preuve d'un talent et d'un engagement remarquables dans l'arène des gladiateurs.",
    -- addon:data.mountdesc.61229:text
    ["The nice thing is that when they attack, blood almost never stains their feathers. -Mei Francis"] = "Ce qu'il y a de bien, c'est que lorsqu'ils attaquent, le sang ne tache presque jamais leurs plumes. -Mei Francis",
    -- addon:professionBook.the_number_of_main_professions_you_can_l:text
    ["The number of main professions you can learn is limited. Jack of All Trades nodes in the Skill Tree unlock more profession slots."] = "Le nombre de métiers principaux que vous pouvez apprendre est limité. Les nœuds Touche-à-tout de l'Arbre des Cendres débloquent d'autres emplacements de métier.",
    -- addon:data.mountdesc.24242:text
    ["The only known Razzashi Raptors were said to have been in the custody of Bloodlord Mandokir in Zul'Gurub.  This species of raptor has not been seen in many years."] = "Les seuls raptors razzashi connus auraient été sous la garde du Seigneur sanglant Mandokir, à Zul'Gurub. Cette espèce de raptor n'a plus été vue depuis de nombreuses années.",
    -- addon:data.mountdesc.60002:text
    ["The only reason for time is so that everything doesn't happen at once."] = "Le temps n'existe que pour que tout n'arrive pas en même temps.",
    -- addon:data.petdesc.67527:text
    ["The onyx panther is invisible at night, like a stalking shadow, and disappears with the dawn."] = "La panthère d'onyx est invisible la nuit, telle une ombre qui rôde, et disparaît à l'aube.",
    -- addon:data.mountdesc.39315:text
    ["The orcs once hunted these graceful herd animals as part of the om'riggor rite of passage ceremony."] = "Les orcs chassaient autrefois ces gracieux animaux de troupeau lors de la cérémonie du rite de passage om'riggor.",
    -- addon:data.petdesc.69541:text
    ["The pandaren monk is a fearless traveling companion, constantly training in his art... unless you offer him a drink. He considers it rude to refuse."] = "Le moine pandaren est un compagnon de voyage intrépide, qui s'entraîne sans cesse à son art... sauf si vous lui offrez un verre. Il trouve impoli de refuser.",
    -- addon:data.petdesc.27570:text
    ["The power of love can be a dangerous thing, especially when wielded by an airborne, ill-tempered goblin."] = "Le pouvoir de l'amour peut être dangereux, surtout entre les mains d'un gobelin volant et colérique.",
    -- addon:data.mountdesc.468:text
    ["The powerful and unyielding white stallion features heavily in the myths of ancient human tribes."] = "Le puissant et inflexible étalon blanc occupe une place de choix dans les mythes des anciennes tribus humaines.",
    -- addon:data.petdesc.61349:text
    ["The rare albino tickbird is revered amongst the Oracles. It is seen as a sign of heavy rainstorms, good grub harvests, and hibernating wolvar."] = "Le rare pique-bœuf albinos est vénéré par les Oracles. On y voit le présage de fortes pluies, de bonnes récoltes de larves et de wolvar en hibernation.",
    -- addon:data.mountdesc.41252:text
    ["The rest be forgotten to walk upon the ground, clipped wings and shame. -Word of the Raven"] = "Les autres seront oubliés, condamnés à marcher sur la terre, les ailes rognées, dans la honte. - Parole du Corbeau",
    -- addon:trials.the_season_being_played:text
    ["The season being played."] = "La saison en cours.",
    -- addon:trials.the_season_mount_traded_for:text
    ["The season mount, traded for one Argent Laurel."] = "La monture de la saison, échangée contre un Laurier d'argent.",
    -- addon:talents.the_server_did_not_answer:text
    ["The server did not answer: nothing was changed."] = "Le serveur n'a pas répondu : rien n'a été modifié.",
    -- addon:data.petdesc.40614:text
    ["The sin'dorei use hawkstriders as mounts, but this little one was deemed unfit after being diagnosed with numerous anxiety disorders."] = "Les sin'dorei montent des faucons-pérégrins, mais ce petit a été jugé inapte après qu'on lui a diagnostiqué de nombreux troubles anxieux.",
    -- addon:contracts.the_spirit_offers_contracts_on:text
    ["The spirit offers contracts on zones and dungeons a few levels above yours. Gain a level or two and come back."] = "L'esprit propose des contrats sur des zones et des donjons de quelques niveaux au-dessus du vôtre. Gagnez un niveau ou deux et revenez.",
    -- addon:data.petdesc.62561:text
    ["The strand crawler has adapted to the northern cold by hibernating under the island beaches."] = "Le rampant des grèves s'est adapté au froid du nord en hibernant sous les plages de l'île.",
    -- addon:data.mountdesc.59572:text
    ["The taunka use black polar bear pelts in their religious rites, usually at the funerals of those who hunt black polar bears."] = "Les taunkas utilisent des peaux d'ours polaire noir dans leurs rites religieux, généralement lors des funérailles de ceux qui chassent les ours polaires noirs.",
    -- addon:data.affix_text.the_third_mind_blast_on_the_same_target:text
    ["The third Mind Blast on the same target opens a Portal of Madness under it for 10 sec. A Crusher Tentacle and two Corruptor Tentacles rise and attack nearby enemies for @value@150%@value@ @range@[30%-150%]@range@ of your Spell Power. Each tick of your Shadow Word: Pain makes them grow (Does not stack)"] = "The third Mind Blast on the same target opens a Portal of Madness under it for 10 sec. A Crusher Tentacle and two Corruptor Tentacles rise and attack nearby enemies for @value@150%@value@ @range@[30%-150%]@range@ of your Spell Power. Each tick of your Shadow Word: Pain makes them grow (Does not stack)",
    -- addon:skillTree.the_tree_spends_the_soul:text
    ["The tree spends the |cffffd700Soul Ashes|r kept on your account. They arrive when you make an |cffffd700offering|r at a Spirit Healer, or when a run ends. This is what you have to spend; hover it to see what it buys."] = "L'arbre dépense les |cffffd700Cendres d'âme|r conservées sur votre compte. Elles arrivent quand vous faites une |cffffd700offrande|r à un Gardien des âmes, ou quand une expédition se termine. Ce montant est ce que vous pouvez dépenser ; survolez-le pour voir ce qu'il permet d'acheter.",
    -- addon:data.petdesc.62513:text
    ["The volatile Durotar scorpion is a fierce desert predator. It's known for only occasionally stinging its owner."] = "L'imprévisible scorpion de Durotar est un redoutable prédateur du désert. On dit qu'il ne pique son maître que de temps en temps.",
    -- addon:data.mountdesc.59961:text
    ["The vrykul were the first to recognize their potential. Or maybe the second, depending on how you look at it."] = "Les vrykuls furent les premiers à reconnaître leur potentiel. Ou peut-être les seconds, selon le point de vue.",
    -- addon:data.mountdesc.23250:text
    ["The wolves of the Horde are befriended, not domesticated."] = "On se lie d'amitié avec les loups de la Horde, on ne les domestique pas.",
    -- addon:data.mountdesc.35025:text
    ["Their plumage is more beautiful than any other. Subtlety is for the birds! I mean... other birds. -Viera Sunwhisper"] = "Leur plumage est plus beau que tous les autres. La discrétion, c'est bon pour les oiseaux ! Enfin... les autres oiseaux. - Viera Murmesoleil",
    -- addon:data.boss.theka_the_martyr:text
    ["Theka the Martyr"] = "Theka le Martyr",
    -- addon:data.affix_family.thekal_s_renewal:text
    ["Thekal's Renewal"] = "Renouveau de Thekal",
    -- addon:data.waystone.thelsamar_loch_modan:text
    ["Thelsamar, Loch Modan"] = "Thelsamar, Loch Modan",
    -- addon:data.waystone.theramore_isle_dustwallow_marsh:text
    ["Theramore Isle, Dustwallow Marsh"] = "Île de Theramore, Marécage d'Âprefange",
    -- addon:collections.gs_transmogrify_invalid_no_item:text
    ["There is no equipped item in this slot."] = "Aucun objet n'est équipé à cet emplacement.",
    -- addon:data.petdesc.15067:text
    ["These adorable critters love snuggling with their owners after a long day of brutal, bloody battle."] = "Ces adorables bestioles adorent se blottir contre leurs maîtres après une longue journée de combats brutaux et sanglants.",
    -- addon:data.petdesc.26533:text
    ["These off-season allies work tirelessly to prepare for the Feast of Winter Veil, and would appreciate not being disturbed the rest of the year."] = "Ces alliés hors saison travaillent sans relâche à préparer la fête du Voile d'hiver, et apprécieraient qu'on ne les dérange pas le reste de l'année.",
    -- addon:data.petdesc.66175:text
    ["These possessed puppets are given a semblance of life by whimsical spirits of the departed."] = "Des esprits facétieux de défunts insufflent un semblant de vie à ces marionnettes possédées.",
    -- addon:data.mountdesc.64927:text
    ["These reanimated vessels of destruction do not fear death; they dispense it."] = "Ces instruments de destruction réanimés ne craignent pas la mort : ils la sèment.",
    -- addon:options.these_settings_change_in_game:text
    ["These settings change in-game console variables (CVars). They persist between sessions."] = "Ces réglages modifient des variables de console du jeu (CVars). Ils sont conservés d'une session à l'autre.",
    -- addon:data.petdesc.48406:text
    ["These stunning creatures, awarded to heroes for victory in battle, represent bravery and strength."] = "Ces créatures splendides, décernées aux héros victorieux au combat, incarnent la bravoure et la force.",
    -- addon:data.petdesc.61350:text
    ["These voracious whelps grow at an incredible rate and can devour nearly twice their weight in raw meat per day."] = "Ces dragonnets voraces grandissent à une vitesse incroyable et peuvent dévorer près de deux fois leur poids en viande crue chaque jour.",
    -- addon:data.petdesc.62746:text
    ["These young orcs strive to embody the Argent Crusade's virtues: valor, strength, and integrity."] = "Ces jeunes orcs s'efforcent d'incarner les vertus de la Croisade d'argent : vaillance, force et intégrité.",
    -- addon:data.mountdesc.61230:text
    ["They are not native to Northrend, but they have adapted extremely well to the cold. -Mei Francis"] = "Ils ne sont pas originaires du Norfendre, mais ils se sont extrêmement bien adaptés au froid. -Mei Francis",
    -- addon:data.mountdesc.32235:text
    ["They love lions in Stormwind, and the gryphon is half lion. Of course they might not like which half. -Gryphon Master Talonaxe"] = "Ils adorent les lions, à Hurlevent, et le griffon est à moitié lion. Bien sûr, ils n'aiment peut-être pas la moitié en question. - Maître des griffons Hachegriffe",
    -- addon:data.affix_family.thick_hide:text
    ["Thick Hide"] = "Peau épaisse",
    -- addon:spec.third:text
    ["Third"] = "Troisième",
    -- addon:data.mountdesc.25953:text
    ["This (relatively) domesticated silithid is at home only in the desert sands of Ahn'Qiraj."] = "Ce silithide (relativement) domestiqué ne se sent chez lui que dans les sables du désert d'Ahn'Qiraj.",
    -- addon:callboard.this_week:text
    ["This Week"] = "Cette semaine",
    -- addon:collections.gs_transmogrify_tooltip_appearance_unusable:text
    ["This appearance can't be used by your character"] = "Votre personnage ne peut pas utiliser cette apparence",
    -- addon:collections.gs_transmog_appearance_usable_holiday:text
    ["This appearance is only usable during holiday: %s."] = "Cette apparence n'est utilisable que pendant l'événement : %s.",
    -- addon:playerRun.this_bar_is_your_contract:text
    ["This bar is your |cffffd700contract bonus|r, up to +400%. It only rises when you fulfil a |cffffd700Death contract|r: 50 creatures in a zone (+10%), every boss of a dungeon (+25%) or a raid (+125%). Dying loses the contracts in progress, never the bonus. |cffff4040Accepting death|r banks your ashes without the bonus, and the bonus is gone. Hover the bar any time to see all of this again."] = "Cette barre est votre |cffffd700bonus de contrat|r, jusqu'à +400%. Elle ne monte que lorsque vous remplissez un |cffffd700contrat de mort|r : 50 créatures dans une zone (+10%), tous les boss d'un donjon (+25%) ou d'un raid (+125%). Mourir fait perdre les contrats en cours, jamais le bonus. |cffff4040Accepter la mort|r verse vos cendres sans le bonus, et le bonus est perdu. Survolez la barre à tout moment pour revoir tout ceci.",
    -- addon:data.mountdesc.459:text
    ["This breed of wolf prefers hunting in the fog, relying on its smoky hide to camouflage it from unsuspecting prey."] = "Cette race de loup préfère chasser dans le brouillard, comptant sur sa robe couleur de fumée pour se camoufler aux yeux de proies sans méfiance.",
    -- addon:perks.fail_invalid_upload:text
    ["This build contains no echoes usable by your class."] = "Ce build ne contient aucun Echo utilisable par votre classe.",
    -- addon:talents.this_build_could_not_be:text
    ["This build could not be applied."] = "Cette configuration n'a pas pu être appliquée.",
    -- addon:data.petdesc.35239:text
    ["This bunny is the cutest thing its opponent will ever see. It'll also be the last."] = "Ce lapin est la chose la plus mignonne que son adversaire verra jamais. Ce sera aussi la dernière.",
    -- addon:data.petdesc.26010:text
    ["This clever toy is equipped with a secret switch to disable its 'tranquil' mode. Luckily, even the engineers who built it don't know how to find it."] = "Cet ingénieux jouet est muni d'un interrupteur secret pour désactiver son mode « tranquille ». Heureusement, même les ingénieurs qui l'ont conçu ne savent pas où le trouver.",
    -- addon:prestige.this_counter_shows_how_many:text
    ["This counter shows how many times you have prestiged. A prestige is a trade: you give up everything your Skill Tree was built on, and you keep one thing forever."] = "Ce compteur indique combien de fois vous avez fait un prestige. Un prestige est un échange : vous renoncez à tout ce sur quoi votre Arbre des Cendres était bâti, et vous gardez une chose pour toujours.",
    -- addon:data.petdesc.67415:text
    ["This crafty raptor was born in the icy wastes of Northrend. Its harsh upbringing gives it strength when many others would perish."] = "Ce raptor rusé est né dans les étendues glacées du Norfendre. Sa rude enfance lui donne la force de survivre là où tant d'autres périraient.",
    -- addon:data.petdesc.28505:text
    ["This cub shares many traits with its relatives, but it's in a league of its own with its singing ability."] = "Ce petit partage de nombreux traits avec ses cousins, mais il est hors catégorie pour ce qui est du chant.",
    -- addon:data.petdesc.10706:text
    ["This dark-feathered bird of prey is often seen as a harbinger of doom amongst the druids of Teldrassil."] = "Cet oiseau de proie au plumage sombre est souvent vu comme un présage funeste par les druides de Teldrassil.",
    -- addon:dungeonFinder.this_difficulty_is_locked:text
    ["This difficulty is locked."] = "Cette difficulté est verrouillée.",
    -- addon:perks.tip_spec_belongs:text
    ["This echo belongs to the {spec} specialization."] = "Cet Echo appartient à la spécialisation {spec}.",
    -- addon:journal.this_echo_will_not_appear:text
    ["This echo will not appear in your draws."] = "Cet Echo n'apparaîtra pas dans vos tirages.",
    -- addon:data.petdesc.66096:text
    ["This extremely rare species of mana wyrm is prized for its unique coloration and even temperament."] = "Cette espèce extrêmement rare de wyrm de mana est prisée pour sa coloration unique et son tempérament égal.",
    -- addon:data.mountdesc.60119:text
    ["This formidable mount is bought with the blood of Alliance leaders, but you would have killed them for free."] = "Cette redoutable monture s'achète avec le sang des chefs de l'Alliance, mais vous les auriez tués gratuitement.",
    -- addon:playerRun.this_frame_follows_your_run:text
    ["This frame follows your run: one life, from level 1 until you |cffff4040accept death|r. What you earn here is not safe yet. It reaches your account, and your |cffffd700Skill Tree|r, when you make an offering at a Spirit Healer or when the run ends."] = "Ce cadre suit votre expédition : une seule vie, du niveau 1 jusqu'à ce que vous choisissiez |cffff4040Accepter la mort|r. Ce que vous gagnez ici n'est pas encore en sécurité. Vos gains rejoignent votre compte et votre |cffffd700Arbre des Cendres|r quand vous faites une offrande auprès d'un Gardien des âmes ou quand l'expédition se termine.",
    -- addon:data.petdesc.45174:text
    ["This golden pig honors its ancestors by giving its allies good fortune."] = "Ce cochon doré honore ses ancêtres en portant chance à ses alliés.",
    -- addon:data.petdesc.67417:text
    ["This hatchling is coveted for its unique coloration. Despite Breanni's loving care, the raptor's feral nature cannot be restrained."] = "Ce petit est convoité pour sa coloration unique. Malgré les soins attentionnés de Breanni, la nature sauvage du raptor ne peut être domptée.",
    -- addon:data.mountdesc.8394:text
    ["This hearty mount's ferocious appetite earned it the nickname \"Dragon Belly\" in the night elf language."] = "L'appétit féroce de cette robuste monture lui a valu le surnom de « Ventre de dragon » dans la langue des elfes de la nuit.",
    -- addon:data.mountdesc.17459:text
    ["This historic piece of gnomish engineering was forced into retirement due to its extremely \"touchy\" gyroscometer."] = "Cette pièce historique de l'ingénierie gnome a dû être retirée du service à cause de son gyroscomètre extrêmement « chatouilleux ».",
    -- addon:torment.this_instance_runs_at_your:text
    ["This instance runs at {here} - your own Torment is {own}."] = "Cette instance se joue en {here}, alors que votre Tourment est {own}.",
    -- addon:data.petdesc.63712:text
    ["This is actually three pets in one. You won't know what you'll get until you summon it!"] = "Ce sont en fait trois familiers en un. Vous ne saurez lequel vous obtiendrez qu'en l'invoquant !",
    -- addon:toolbelt.fail_locked:text
    ["This is not unlocked on this character. It is sold in the shop."] = "Cette fonction n'est pas débloquée sur ce personnage. Elle est en vente dans la boutique.",
    -- addon:collections.gs_heirlooms_journal_tutorial_upgrade:text
    ["This is the max level of the heirloom. You can raise this level by using special upgrade tokens."] = "Ceci est le niveau maximal de l'héritage. Vous pouvez l'augmenter à l'aide de jetons d'amélioration spéciaux.",
    -- addon:journal.this_is_your_active_loadout:text
    ["This is your active loadout."] = "Ceci est votre configuration active.",
    -- addon:collections.gs_transmogrify_tooltip_appearance_uncollectable:text
    ["This item can't be used for transmogrification, but may be worn as equipment"] = "Cet objet ne peut pas servir à la transmogrification, mais peut être porté comme équipement",
    -- addon:collections.gs_transmogrify_invalid_destination:text
    ["This item cannot be transmogrified."] = "Cet objet ne peut pas être transmogrifié.",
    -- addon:affixToast.this_item_carries_an_affix:text
    ["This item carries an affix. While you wear the item, you benefit from it, but looting it does |cffff8040not|r teach it to you."] = "Cet objet porte un affixe. Tant que vous le portez, vous en bénéficiez, mais le ramasser ne vous l'apprend |cffff8040pas|r.",
    -- addon:extraction.tip_no_affix:text
    ["This item carries no affix."] = "Cet objet ne porte aucun affixe.",
    -- addon:collections.gs_transmogrify_invalid_not_soulbound:text
    ["This item is not soulbound."] = "Cet objet n'est pas lié.",
    -- addon:extraction.this_item_takes_no_affix:text
    ["This item takes no affix"] = "Cet objet n'accepte aucun affixe",
    -- addon:collections.gs_transmogrify_invalid_mismatch:text
    ["This item type isn't compatible with this appearance."] = "Ce type d'objet n'est pas compatible avec cette apparence.",
    -- addon:data.petdesc.28871:text
    ["This little piece of summer smells of warm evenings and lightning storms. If you look closely, you might be able to make out a face."] = "Ce petit morceau d'été sent les soirées chaudes et les orages. En regardant bien, vous distinguerez peut-être un visage.",
    -- addon:perks.fail_locked:text
    ["This loadout slot is locked - unlock it with gold first."] = "Cet emplacement de configuration est verrouillé : débloquez-le d'abord avec de l'or.",
    -- addon:data.petdesc.54187:text
    ["This mechanical warrior is a favorite gift during Winter Veil. Batteries not included, but rockets definitely are!"] = "Ce guerrier mécanique est un cadeau très prisé pendant le Voile d'hiver. Piles non fournies, mais les fusées, elles, le sont !",
    -- addon:journal.this_menu_manages_your_builds:text
    ["This menu manages your builds. |cff60a0e0Loadouts|r are independent echo builds, each with its own echoes, locked echoes, banishes, rerolls and freezes. Switch between them at any level: the one you arrive on is handed every draw your level owes it. Death empties them all, locked echoes excepted.\n\n|cffa080e0Wishlists|r are for |cffffd700designing|r: the echoes you wish to collect, assembled into your dream build. Create one with |cffffd700New Wishlist|r, pick its echoes in the catalog, then |cffffd700Done|r. While it is active, its echoes are highlighted in your draws to guide you toward it."] = "Ce menu gère vos builds. Les |cff60a0e0configurations|r sont des builds d'Echos indépendants, chacun avec ses propres Echos, Echos verrouillés, bannissements, relances et gels. Passez de l'une à l'autre à n'importe quel niveau : celle sur laquelle vous arrivez reçoit tous les tirages que votre niveau lui doit. La mort les vide toutes, à l'exception des Echos verrouillés.\n\nLes |cffa080e0listes de souhaits|r servent à |cffffd700concevoir|r : les Echos que vous souhaitez collectionner, réunis pour former votre build de rêve. Créez-en une avec |cffffd700Nouvelle liste de souhaits|r, choisissez ses Echos dans le catalogue, puis |cffffd700Terminé|r. Tant qu'elle est active, ses Echos sont mis en évidence dans vos tirages pour vous guider vers elle.",
    -- addon:data.petdesc.42609:text
    ["This mischievous gourd likes to pop out of the ground and scare you right out of your pants. Hail to the pumpkin song!"] = "Cette courge espiègle aime surgir du sol et vous faire une peur bleue. Gloire au chant de la citrouille !",
    -- addon:data.petdesc.67416:text
    ["This offspring of Takk the Leaper is incredibly agile and can maneuver through difficult environments with ease."] = "Ce rejeton de Takk le Bondisseur est incroyablement agile et se faufile sans peine dans les environnements difficiles.",
    -- addon:data.petdesc.17707:text
    ["This pint-sized panda cub is highly sought after by adventurers around Azeroth - despite its narcoleptic nature."] = "Ce bébé panda de poche est très recherché par les aventuriers de tout Azeroth, malgré sa nature narcoleptique.",
    -- addon:data.mountdesc.63635:text
    ["This raptor breed was originally cultivated by the Drakkari, but has since been adopted by the Darkspear tribe in Northrend."] = "Cette race de raptor fut d'abord élevée par les Drakkari, mais elle a depuis été adoptée par la tribu Sombrelance en Norfendre.",
    -- addon:data.petdesc.61855:text
    ["This rare bear is bred for its small size and perpetually youthful appearance."] = "Cet ours rare est élevé pour sa petite taille et son air éternellement juvénile.",
    -- addon:collections.gs_transmog_set_limited_time_set_tooltip:text
    ["This set can be collected during the current season only."] = "Cet ensemble ne peut être collecté que pendant la saison en cours.",
    -- addon:perks.fail_empty:text
    ["This slot is empty."] = "Cet emplacement est vide.",
    -- addon:data.petdesc.15049:text
    ["This tiny peacekeeper security bot is often outfitted with the latest arcane nullifiers and crowd pummelers. Not for the environmentally minded."] = "Ce minuscule robot de sécurité de type gardien de la paix est souvent équipé des derniers annulateurs arcaniques et matraqueurs de foule. Déconseillé aux écologistes.",
    -- addon:collections.gs_transmogrify_invalid_item_type:text
    ["This type of item cannot be transmogrified."] = "Ce type d'objet ne peut pas être transmogrifié.",
    -- addon:data.mountdesc.60114:text
    ["This ursine mount's swiftness is enhanced by its heavy armor, imbued with magic from Kirin Tor magi."] = "La rapidité de cette monture ursine est renforcée par sa lourde armure, imprégnée de la magie des mages du Kirin Tor.",
    -- addon:callboard.this_week_2:text
    ["This week"] = "Cette semaine",
    -- addon:data.mountdesc.59793:text
    ["This wild variant of the mammoth is not bred for riding. Most wooly mammoths are captured in the wild and tamed by their riders, resulting in a fierce, cunning mount."] = "Cette variété sauvage de mammouth n'est pas élevée pour être montée. La plupart des mammouths laineux sont capturés à l'état sauvage et apprivoisés par leurs cavaliers, ce qui donne une monture féroce et rusée.",
    -- addon:prestige.this_will_erase:text
    ["This will ERASE"] = "Ceci EFFACERA",
    -- addon:data.petdesc.71840:text
    ["This, um, 'adorable' little guy likes to play with critters. Just don't let them get too close."] = "Ce petit gars, euh... « adorable », aime jouer avec les bestioles. Mais ne les laissez pas trop approcher.",
    -- addon:data.waystone.thondoril_river_western_plaguelands:text
    ["Thondoril River, Western Plaguelands"] = "La Thondroril, Maleterres de l'ouest",
    -- addon:data.petdesc.69536:text
    ["Thorg No-Legs never paid heed to the old orc saying, 'Don't pull a wyvern's tail.'"] = "Thorg No-Legs n'a jamais prêté attention au vieux dicton orc : « Ne tire pas la queue d'une wyverne. »",
    -- addon:data.boss.thorim:text
    ["Thorim"] = "Thorim",
    -- addon:data.affix_family.thorim_s_static_shield:text
    ["Thorim's Static Shield"] = "Bouclier statique de Thorim",
    -- addon:data.waystone.thorium_point_searing_gorge:text
    ["Thorium Point, Searing Gorge"] = "Halte du Thorium, gorge des Vents brûlants",
    -- addon:data.boss.thorngrin_the_tender:text
    ["Thorngrin the Tender"] = "Rirépine le Tendre",
    -- addon:data.affix_family.thorns:text
    ["Thorns"] = "Epines",
    -- addon:data.graveyard.thousand_needles_freewind_post:text
    ["Thousand Needles, Freewind Post"] = "Mille pointes, Poste de Librevent",
    -- addon:data.graveyard.thousand_needles_mirage_raceway:text
    ["Thousand Needles, Mirage Raceway"] = "Mille pointes, Piste des mirages",
    -- addon:data.graveyard.thousand_needles_shimmering_flats:text
    ["Thousand Needles, Shimmering Flats"] = "Mille pointes, les Salines",
    -- addon:data.graveyard.thousand_needles_the_great_lift:text
    ["Thousand Needles, The Great Lift"] = "Mille pointes, la Grande élévation",
    -- addon:data.waystone.thrallmar_hellfire_peninsula:text
    ["Thrallmar, Hellfire Peninsula"] = "Thrallmar, péninsule des Flammes infernales",
    -- addon:perks.spec_banner_sub2:text
    ["Three echoes of the specialization you chose at level 10"] = "Trois Echos de la spécialisation choisie au niveau 10",
    -- addon:collections.cat_thrown:text
    ["Thrown"] = "Armes de jet",
    -- addon:data.waystone.thunder_bluff_mulgore:text
    ["Thunder Bluff, Mulgore"] = "Les Pitons du Tonnerre, Mulgore",
    -- addon:data.waystone.thunderlord_stronghold_blade_s_edge_moun:text
    ["Thunderlord Stronghold, Blade's Edge Mountains"] = "Bastion des Sire-tonnerre, les Tranchantes",
    -- addon:data.affix_text.thunderstorm_pulls_enemies_toward_you_in:text
    ["Thunderstorm pulls enemies toward you instead of knocking them back, and slows them by @value@60%@value@ @range@[20%-60%]@range@ for 6 sec (Does not stack)"] = "Thunderstorm pulls enemies toward you instead of knocking them back, and slows them by @value@60%@value@ @range@[20%-60%]@range@ for 6 sec (Does not stack)",
    -- addon:raidFinder.tick_every_role_you_can_play_you_get_the:text
    ["Tick every role you can play: you get the seat the raid is missing."] = "Cochez chaque rôle que vous pouvez jouer : vous obtenez la place qui manque au raid.",
    -- addon:dungeonFinder.ticked_other_players_join_you:text
    ["Ticked: other players join you until the run has 5 players. It starts with 2 to 5."] = "Coché : d'autres joueurs vous rejoignent jusqu'à ce que l'expédition compte 5 joueurs. Elle démarre avec 2 à 5 joueurs.",
    -- addon:customTicket.ticket_d_created_a_gm:text
    ["Ticket #%d created. A GM will respond as soon as possible."] = "Ticket n°%d créé. Un MJ vous répondra dès que possible.",
    -- addon:customTicket.ticket_creation_failed:text
    ["Ticket creation failed: {reason}"] = "Échec de la création du ticket : {reason}",
    -- addon:customTicket.ticket_submitted_waiting_for_server:text
    ["Ticket submitted. Waiting for server confirmation..."] = "Ticket envoyé. En attente de la confirmation du serveur...",
    -- addon:data.affix_family.tidal_shield:text
    ["Tidal Shield"] = "Bouclier de flots",
    -- addon:data.affix_family.tidal_wave:text
    ["Tidal Wave"] = "Raz-de-marée",
    -- addon:contracts.time:text
    ["Time"] = "Temps",
    -- addon:raidFinder.time_searching_time:text
    ["Time Searching: {time}"] = "Temps de recherche : {time}",
    -- addon:raidFinder.time_in_queue_time:text
    ["Time in Queue: {time}"] = "Temps en file d'attente : {time}",
    -- addon:trials.time_is_up:text
    ["Time is up."] = "Le temps est écoulé.",
    -- addon:contracts.time_left:text
    ["Time left"] = "Temps restant",
    -- addon:trials.time:text
    ["Time {ds}  -  {detail}"] = "Temps {ds}  -  {detail}",
    -- addon:data.boss.timmy_the_cruel:text
    ["Timmy the Cruel"] = "Timmy le Cruel",
    -- addon:data.boss.tinkerer_gizlock:text
    ["Tinkerer Gizlock"] = "Bricoleur Kadenaz",
    -- addon:collections.gs_toybox_mousewheel_paging_help:text
    ["Tip: You can use your mouse wheel to quickly page through the Toy Box."] = "Astuce : utilisez la molette de la souris pour parcourir rapidement les pages du coffre à jouets.",
    -- addon:data.zone.tirisfal_glades:text
    ["Tirisfal Glades"] = "Clairières de Tirisfal",
    -- addon:data.graveyard.tirisfal_glades_brill:text
    ["Tirisfal Glades, Brill"] = "Clairières de Tirisfal, Brill",
    -- addon:data.graveyard.tirisfal_glades_deathknell:text
    ["Tirisfal Glades, Deathknell"] = "Clairières de Tirisfal, Le Glas",
    -- addon:data.graveyard.tirisfal_glades_undercity:text
    ["Tirisfal Glades, Undercity"] = "Clairières de Tirisfal, Fossoyeuse",
    -- addon:prestige.title:text
    ["Title: {name}"] = "Titre : {name}",
    -- addon:trials.title:text
    ["Title: {player} {title}"] = "Titre : {player} {title}",
    -- addon:collections.gs_transmogrify_tooltip_revert:text
    ["To be reverted"] = "Sera rétabli",
    -- addon:collections.gs_will_be_transmogrified_header:text
