    -- addon:data.mountdesc.63637:text
    ["When a night elf's mount perishes, it is custom for the rider to keep one of the saber's great fangs as a token of remembrance."] = "Lorsque la monture d'un elfe de la nuit périt, la coutume veut que le cavalier conserve l'un des grands crocs du sabre en souvenir.",
