    -- addon:data.affix_text.when_you_fall_below_40_health_you_are_he:text
    ["When you fall below 40% health, you are healed for 20% of your maximum health; cannot occur more than once every @value@40 sec@value@ @range@[120 sec-40 sec]@range@ (Does not stack)"] = "When you fall below 40% health, you are healed for 20% of your maximum health; cannot occur more than once every @value@40 sec@value@ @range@[120 sec-40 sec]@range@ (Does not stack)",
