    -- addon:skillTree.you_are_about_to_spend:text
    ["You are about to spend Soul Ashes on your Skill Tree.\n\nThis is |cffFF0000final|r: once applied, a rank can never be unlearned and its Soul Ashes are never refunded. Only a |cffFF4444Prestige|r resets the tree, and the octagon-framed nodes survive even that."] = "Vous êtes sur le point de dépenser des Cendres d'âme dans votre Arbre des Cendres.\n\nC'est |cffFF0000définitif|r : une fois appliqué, un rang ne peut jamais être désappris et ses Cendres d'âme ne sont jamais remboursées. Seul un |cffFF4444Prestige|r réinitialise l'arbre, et les nœuds à cadre octogonal survivent même à celui-ci.",
    -- addon:perks.fail_same:text
    ["You are already playing this loadout."] = "Vous utilisez déjà cette configuration.",
