    -- addon:data.affix_text.your_fire_damage_may_hurl_a_fiery_ball_d:text
    ["Your Fire damage may hurl a fiery ball dealing @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Fire damage, plus the same amount over 8 sec (Does not stack)"] = "Your Fire damage may hurl a fiery ball dealing @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Fire damage, plus the same amount over 8 sec (Does not stack)",
    -- addon:data.affix_text.your_frost_damage_may_launch_a_bolt_of_f:text
    ["Your Frost damage may launch a bolt of frost dealing @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Frost damage and slowing the target by 30% for 5 sec, increased by 20% per slowing effect on the target (Does not stack)"] = "Your Frost damage may launch a bolt of frost dealing @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Frost damage and slowing the target by 30% for 5 sec, increased by 20% per slowing effect on the target (Does not stack)",
    -- addon:data.affix_text.your_immolate_leaves_a_trail_of_doomfire:text
    ["Your Immolate leaves a trail of Doomfire behind the target as it moves: enemies in it burn for @value@50%@value@ @range@[10%-50%]@range@ of your Spell Power every second (Does not stack)"] = "Your Immolate leaves a trail of Doomfire behind the target as it moves: enemies in it burn for @value@50%@value@ @range@[10%-50%]@range@ of your Spell Power every second (Does not stack)",
    -- addon:data.affix_text.your_nature_damage_may_coat_the_target_i:text
    ["Your Nature damage may coat the target in Corrosive Acid dealing @value@67%@value@ @range@[13%-67%]@range@ of your Spell Power or Attack Power as Nature damage every 3 sec for 15 sec and reducing its armor by 10% per periodic effect you have on it (up to 30%) (Does not stack)"] = "Your Nature damage may coat the target in Corrosive Acid dealing @value@67%@value@ @range@[13%-67%]@range@ of your Spell Power or Attack Power as Nature damage every 3 sec for 15 sec and reducing its armor by 10% per periodic effect you have on it (up to 30%) (Does not stack)",
    -- addon:raidFinder.your_raid_finder_raid_n_total_players:text
