    -- addon:data.affix_text.your_shadow_damage_may_send_a_shadowy_bo:text
    ["Your Shadow damage may send a shadowy bolt dealing @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Shadow damage, increased by 20% per Shadow periodic effect you have on the target (Does not stack)"] = "Your Shadow damage may send a shadowy bolt dealing @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Shadow damage, increased by 20% per Shadow periodic effect you have on the target (Does not stack)",
    -- addon:skillTree.your_skill_tree:text
    ["Your Skill Tree"] = "Votre Arbre des Cendres",
    -- addon:prestige.your_skill_tree_is_reset:text
    ["Your Skill Tree is reset, and every Soul Ash on the account is destroyed: the ones you banked and the ones already spent, on every character. The Ashes buy nothing back. Only |cff00FF00Carry over Prestige|r nodes survive the reset, and they become free for good. Every |cff00FF00Endless|r node is one of them: all its ranks stay."] = "Votre Arbre des Cendres est réinitialisé, et chaque Cendre d'âme du compte est détruite : celles que vous aviez en banque et celles déjà dépensées, sur tous les personnages. Les Cendres ne rachètent rien. Seuls les nœuds |cff00FF00Report de Prestige|r survivent à la réinitialisation, et ils deviennent gratuits pour de bon. Chaque nœud |cff00FF00Sans fin|r en fait partie : tous ses rangs restent.",
    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_20:text
    ["Your Spirit Wolves heal you for @value@20%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)"] = "Your Spirit Wolves heal you for @value@20%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)",
    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_30:text
