    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_40:text
    ["Your Spirit Wolves heal you for @value@40%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)"] = "Your Spirit Wolves heal you for @value@40%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)",
    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_50:text
    ["Your Spirit Wolves heal you for @value@50%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)"] = "Your Spirit Wolves heal you for @value@50%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)",
    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_60:text
    ["Your Spirit Wolves heal you for @value@60%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)"] = "Your Spirit Wolves heal you for @value@60%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)",
