    -- addon:raidLockout.raids_have_no_id_join:text
    ["|cffFFCC00Raids have no ID: join any group, any time.\nEach boss can be looted once a week.\nRaid Info lists the bosses you looted.|r"] = "|cffFFCC00Les raids n'ont pas d'identifiant : rejoignez n'importe quel groupe, à tout moment.\nChaque boss peut être pillé une fois par semaine.\nLe panneau Infos raid affiche les boss que vous avez pillés.|r",
    -- addon:prestige.soul_essence_buys_the_prestige:text
    ["|cffFFCC00Soul Essence|r buys the Prestige branch, and no prestige takes it back."] = "L'|cffFFCC00Essence d'âme|r permet d'acheter la branche Prestige, et aucun prestige ne la reprend.",
    -- addon:journal.left_click_to_forget_one:text
    ["|cffFFD100Left-click to forget one stack now|r"] = "|cffFFD100Clic gauche pour oublier un cumul maintenant|r",
    -- addon:perks.orb_help:text
    ["|cffFFD100Orb of Lost Memories|r\n\n|cffFFD100Left-click|r an Echo to forget a stack, or |cffFFD100right-click|r several to forget them together, one Orb each.\n\nEach draws a new Echo choice. Your |cffFF8080reroll, freeze and banish|r do not apply to those draws; |cffFFD100another Orb|r redraws them."] = "|cffFFD100Orbe des souvenirs perdus|r\n\n|cffFFD100Clic gauche|r sur un Echo pour en oublier un cumul, ou |cffFFD100clic droit|r sur plusieurs pour les oublier ensemble, à raison d'un orbe par Echo.\n\nChacun tire un nouveau choix d'Echo. Votre |cffFF8080relance, votre gel et votre bannissement|r ne s'appliquent pas à ces tirages ; |cffFFD100un autre orbe|r les relance.",
    -- addon:spellUnlearn.right_click_an_echo_to:text
    ["|cffFFD100Right-click an Echo to unlearn it|r"] = "|cffFFD100Clic droit sur un Echo pour le désapprendre|r",
